use anyhow::{anyhow, Result};
use regex::{Regex, RegexBuilder};
use std::fs;
use std::io::{self, BufRead, Read};
use std::path::{Path, PathBuf};
use walkdir::WalkDir;
use std::sync::{Arc, Mutex};

mod args;
mod matcher;
mod output;
mod ignore;

use args::Args;
use matcher::Matcher;
use output::OutputFormatter;
use ignore::IgnoreManager;

fn main() -> Result<()> {
    let args = Args::parse()?;

    if args.version {
        println!("ag version 2.2.0\n");
        println!("Features:");
        println!("  +jit +lzma +zlib");
        return Ok(());
    }

    if args.list_file_types {
        print_file_types();
        return Ok(());
    }

    if args.pattern.is_empty() && args.paths.is_empty() {
        return Err(anyhow!("Pattern required"));
    }

    let matcher = Matcher::new(&args)?;
    let ignore_manager = IgnoreManager::new(&args);
    let formatter = OutputFormatter::new(&args);

    let paths = if args.paths.is_empty() {
        vec![PathBuf::from(".")]
    } else {
        args.paths.clone()
    };

    let mut found_match = false;

    for path in paths {
        if path.is_file() {
            search_file(&path, &matcher, &formatter, &mut found_match, &args)?;
        } else if path.is_dir() {
            search_directory(
                &path,
                &matcher,
                &formatter,
                &ignore_manager,
                &mut found_match,
                &args,
            )?;
        }
    }

    // Check if we're reading from stdin when no paths provided
    if args.paths.is_empty() && atty::isnt(atty::Stream::Stdin) {
        search_stdin(&matcher, &formatter, &mut found_match, &args)?;
    }

    Ok(())
}

fn search_file(
    path: &Path,
    matcher: &Matcher,
    formatter: &OutputFormatter,
    found_match: &mut bool,
    args: &Args,
) -> Result<()> {
    let content = fs::read_to_string(path)?;
    let matches = matcher.find_all(&content);

    if !matches.is_empty() {
        *found_match = true;
        formatter.print_matches(path, &content, &matches, args);
    }

    Ok(())
}

fn search_directory(
    dir: &Path,
    matcher: &Matcher,
    formatter: &OutputFormatter,
    ignore_manager: &IgnoreManager,
    found_match: &mut bool,
    args: &Args,
) -> Result<()> {
    let walker = WalkDir::new(dir)
        .max_depth(if args.norecurse { 1 } else { args.depth });

    for entry in walker {
        let entry = entry?;
        let path = entry.path();

        if path.is_file() {
            if ignore_manager.should_ignore(path, args) {
                continue;
            }

            if let Ok(content) = fs::read_to_string(path) {
                let matches = matcher.find_all(&content);
                if !matches.is_empty() {
                    *found_match = true;
                    formatter.print_matches(path, &content, &matches, args);
                }
            }
        }
    }

    Ok(())
}

fn search_stdin(
    matcher: &Matcher,
    formatter: &OutputFormatter,
    found_match: &mut bool,
    args: &Args,
) -> Result<()> {
    let stdin = io::stdin();
    let reader = stdin.lock();
    let mut content = String::new();
    let mut line_num = 0;

    for line in reader.lines() {
        line_num += 1;
        let line = line?;
        let matches = matcher.find_all(&line);

        if !matches.is_empty() {
            *found_match = true;
            // Format for stdin
        }
    }

    Ok(())
}

fn print_file_types() {
    let types = vec![
        ("actionscript", vec![".as", ".mxml"]),
        ("ada", vec![".ada", ".adb", ".ads"]),
        ("asciidoc", vec![".adoc", ".ad", ".asc", ".asciidoc"]),
        ("apl", vec![".apl"]),
        ("asm", vec![".asm", ".s"]),
        ("asp", vec![".asp", ".asa", ".aspx", ".asax", ".ashx", ".ascx", ".asmx"]),
        ("c", vec![".c", ".h"]),
        ("cc", vec![".cc", ".cpp", ".cxx", ".h", ".hpp"]),
        ("go", vec![".go"]),
        ("html", vec![".htm", ".html", ".shtml", ".xhtml"]),
        ("java", vec![".java"]),
        ("javascript", vec![".js"]),
        ("python", vec![".py"]),
        ("ruby", vec![".rb"]),
        ("rust", vec![".rs"]),
        ("shell", vec![".sh", ".bash"]),
    ];

    println!("The following file types are supported:");
    for (name, exts) in types {
        println!("  --{}", name);
        for ext in exts {
            print!("      {}", ext);
        }
        println!();
    }
}
