    pub ignore_case: bool,
    pub smart_case: bool,
    pub word_regexp: bool,
    pub literal: bool,
    pub multiline: bool,
    pub invert_match: bool,
    pub max_count: usize,
    pub norecurse: bool,
    pub depth: usize,
    pub follow: bool,
    pub unrestricted: bool,
    pub skip_vcs_ignores: bool,
    pub search_hidden: bool,
    pub search_binary: bool,
    pub all_types: bool,
    pub all_text: bool,

    // Output options
    pub count: bool,
    pub files_with_matches: bool,
    pub files_without_matches: bool,
    pub only_matching: bool,
    pub color: bool,
    pub break_on_file: bool,
    pub group: bool,
    pub heading: bool,
    pub filename: bool,
    pub numbers: bool,
    pub column: bool,
    pub vimgrep: bool,
    pub null_separator: bool,
    pub print_all_files: bool,
    pub passthrough: bool,
    pub print_long_lines: bool,
    pub silent: bool,
    pub stats: bool,
    pub stats_only: bool,
    pub ackmate: bool,

    // Context
    pub before_context: Option<usize>,
    pub after_context: Option<usize>,
    pub context: Option<usize>,
    pub width: Option<usize>,

    // Color codes
    pub color_path: String,
    pub color_line_number: String,
    pub color_match: String,

    // Other
    pub pager: Option<String>,
    pub ignore_patterns: Vec<String>,
    pub ignore_file: Option<PathBuf>,
}

impl Args {
    pub fn parse() -> Result<Self> {
        let args: Vec<String> = std::env::args().collect();

        let mut result = Args {
            pattern: String::new(),
            paths: Vec::new(),
            version: false,
            list_file_types: false,
            case_sensitive: false,
            ignore_case: false,
            smart_case: true,
            word_regexp: false,
            literal: false,
            multiline: true,
            invert_match: false,
            max_count: 10000,
            norecurse: false,
            depth: 25,
            follow: false,
            unrestricted: false,
            skip_vcs_ignores: false,
            search_hidden: false,
            search_binary: false,
            all_types: false,
            all_text: false,
            count: false,
            files_with_matches: false,
            files_without_matches: false,
            only_matching: false,
            color: true,
            break_on_file: true,
            group: true,
            heading: true,
            filename: true,
            numbers: false,
            column: false,
            vimgrep: false,
            null_separator: false,
            print_all_files: false,
            passthrough: false,
            print_long_lines: false,
            silent: false,
            stats: false,
            stats_only: false,
            ackmate: false,
            before_context: None,
            after_context: None,
            context: None,
            width: None,
            color_path: "1;32".to_string(),
            color_line_number: "1;33".to_string(),
            color_match: "30;43".to_string(),
            pager: None,
            ignore_patterns: Vec::new(),
            ignore_file: None,
        };

        let mut i = 1;
        let mut pattern_found = false;

        while i < args.len() {
            let arg = &args[i];

            if arg == "--version" || arg == "-V" {
                result.version = true;
                i += 1;
            } else if arg == "--list-file-types" {
                result.list_file_types = true;
                i += 1;
            } else if arg == "--" {
                i += 1;
                // Rest are paths
                if !pattern_found && i < args.len() {
                    result.pattern = args[i].clone();
                    pattern_found = true;
                    i += 1;
                }
                while i < args.len() {
                    result.paths.push(PathBuf::from(&args[i]));
                    i += 1;
                }
            } else if arg.starts_with('-') && !pattern_found {
                i = parse_flag(&args, i, &mut result)?;
            } else if !pattern_found {
                result.pattern = arg.clone();
                pattern_found = true;
                i += 1;
            } else {
                result.paths.push(PathBuf::from(arg));
                i += 1;
            }
        }

        Ok(result)
    }
}

fn parse_flag(args: &[String], mut i: usize, result: &mut Args) -> Result<usize> {
    let arg = &args[i];

    match arg.as_str() {
        "-i" | "--ignore-case" => result.ignore_case = true,
        "-s" | "--case-sensitive" => {
            result.case_sensitive = true;
            result.smart_case = false;
        }
        "-S" | "--smart-case" => result.smart_case = true,
        "-w" | "--word-regexp" => result.word_regexp = true,
        "-Q" | "--literal" | "-F" | "--fixed-strings" => result.literal = true,
        "-v" | "--invert-match" => result.invert_match = true,
        "-c" | "--count" => result.count = true,
        "-l" | "--files-with-matches" => result.files_with_matches = true,
        "-L" | "--files-without-matches" => result.files_without_matches = true,
        "-o" | "--only-matching" => result.only_matching = true,
        "--nocolor" | "--no-color" => result.color = false,
        "--color" => result.color = true,
        "--nobreak" | "--no-break" => result.break_on_file = false,
        "--break" => result.break_on_file = true,
        "--nogroup" | "--no-group" => result.group = false,
        "--group" => result.group = true,
        "-H" | "--heading" => result.heading = true,
        "--noheading" | "--no-heading" => result.heading = false,
        "--nofilename" | "--no-filename" => result.filename = false,
        "--filename" => result.filename = true,
        "--numbers" => result.numbers = true,
        "--nonumbers" | "--no-numbers" => result.numbers = false,
        "--column" => result.column = true,
        "--vimgrep" => result.vimgrep = true,
        "-0" | "--null" | "--print0" => result.null_separator = true,
        "--print-all-files" => result.print_all_files = true,
        "--passthrough" | "--passthru" => result.passthrough = true,
        "--print-long-lines" => result.print_long_lines = true,
        "--silent" => result.silent = true,
        "--stats" => result.stats = true,
        "--stats-only" => result.stats_only = true,
        "--ackmate" => result.ackmate = true,
        "-n" | "--norecurse" => result.norecurse = true,
        "-r" | "--recurse" => result.norecurse = false,
        "-f" | "--follow" => result.follow = true,
        "-u" | "--unrestricted" => result.unrestricted = true,
        "-U" | "--skip-vcs-ignores" => result.skip_vcs_ignores = true,
        "--hidden" => result.search_hidden = true,
        "--search-binary" => result.search_binary = true,
        "-a" | "--all-types" => result.all_types = true,
        "-t" | "--all-text" => result.all_text = true,
        "-D" | "--debug" => {}, // Ignore debug for now
        "-A" | "--after" => {
            i += 1;
            result.after_context = Some(if i < args.len() {
                args[i].parse().unwrap_or(2)
            } else {
                2
            });
        }
        "-B" | "--before" => {
            i += 1;
            result.before_context = Some(if i < args.len() {
                args[i].parse().unwrap_or(2)
            } else {
                2
            });
        }
        "-C" | "--context" => {
            i += 1;
            result.context = Some(if i < args.len() {
                args[i].parse().unwrap_or(2)
            } else {
                2
            });
        }
        "-W" | "--width" => {
            i += 1;
            if i < args.len() {
                result.width = Some(args[i].parse()?);
            }
        }
        "--depth" => {
            i += 1;
            if i < args.len() {
                result.depth = args[i].parse().unwrap_or(25);
            }
        }
        "-m" | "--max-count" => {
            i += 1;
            if i < args.len() {
                result.max_count = args[i].parse().unwrap_or(10000);
            }
        }
        "--ignore" | "--ignore-dir" => {
            i += 1;
            if i < args.len() {
                result.ignore_patterns.push(args[i].clone());
            }
        }
        "-p" | "--path-to-ignore" => {
            i += 1;
            if i < args.len() {
                result.ignore_file = Some(PathBuf::from(&args[i]));
            }
        }
        "--pager" => {
            i += 1;
            if i < args.len() {
                result.pager = Some(args[i].clone());
            }
        }
        "--color-path" => {
            i += 1;
            if i < args.len() {
                result.color_path = args[i].clone();
            }
        }
        "--color-line-number" => {
            i += 1;
            if i < args.len() {
                result.color_line_number = args[i].clone();
            }
        }
        "--color-match" => {
            i += 1;
            if i < args.len() {
                result.color_match = args[i].clone();
            }
        }
        "-g" => {
            i += 1;
            // Filename pattern - not implemented for now
        }
        "-G" | "--file-search-regex" => {
            i += 1;
            // File search regex - not implemented for now
        }
        _ => {
            if arg.starts_with("--color-") {
                i += 1;
                if i < args.len() {
                    i += 1;
                }
            } else {
                i += 1;
            }
        }
    }

    Ok(i + 1)
}
