use anyhow::Result;
use regex::{Regex, RegexBuilder};
use crate::args::Args;

#[derive(Debug, Clone)]
pub struct Match {
    pub line_num: usize,
    pub col: usize,
    pub matched_text: String,
    pub line_text: String,
}

pub struct Matcher {
    regex: Regex,
    literal: bool,
}

impl Matcher {
    pub fn new(args: &Args) -> Result<Self> {
        let pattern = &args.pattern;

        let regex = if args.literal {
            // Escape regex special characters
            let escaped = regex::escape(pattern);
            build_regex(&escaped, args)?
        } else {
            build_regex(pattern, args)?
        };

        Ok(Matcher {
            regex,
            literal: args.literal,
        })
    }

    pub fn find_all(&self, text: &str) -> Vec<Match> {
        let mut matches = Vec::new();

        for (line_num, line) in text.lines().enumerate() {
            for mat in self.regex.find_iter(line) {
                matches.push(Match {
                    line_num: line_num + 1,
                    col: mat.start() + 1,
                    matched_text: mat.as_str().to_string(),
                    line_text: line.to_string(),
                });
            }
        }

        matches
    }

    pub fn is_match(&self, text: &str) -> bool {
        self.regex.is_match(text)
    }
}

fn build_regex(pattern: &str, args: &Args) -> Result<Regex> {
    let mut builder = RegexBuilder::new(pattern);

    if args.ignore_case {
        builder.case_insensitive(true);
    } else if args.smart_case && !pattern.chars().any(|c| c.is_uppercase()) {
        builder.case_insensitive(true);
    }

    if !args.multiline {
        builder.multi_line(false);
    }

    if args.word_regexp {
        let word_pattern = format!(r"\b{}\b", pattern);
        let regex = builder.build(&word_pattern)?;
        Ok(regex)
    } else {
        let regex = builder.build(pattern)?;
        Ok(regex)
    }
}
