use std::env;
use std::fs;
use std::io::{self, BufRead, Read};
use std::path::{Path, PathBuf};
use std::process;

mod args;
mod matcher;
mod output;
mod ignore;

use args::Args;
use matcher::Matcher;
use output::OutputFormatter;

fn main() {
    let args = match Args::parse() {
        Ok(a) => a,
        Err(e) => {
            eprintln!("Error: {}", e);
            process::exit(1);
        }
    };

    if args.version {
        println!("ag version 2.2.0\n");
        println!("Features:");
        println!("  +jit +lzma +zlib");
        return;
    }

    if args.list_file_types {
        print_file_types();
        return;
    }

    if args.pattern.is_empty() && !args.help {
        print_usage();
        return;
    }

    let matcher = match Matcher::new(&args) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Regex error: {}", e);
            process::exit(1);
        }
    };

    let formatter = OutputFormatter::new(&args);

    let paths = if args.paths.is_empty() {
        vec![PathBuf::from(".")]
    } else {
        args.paths.clone()
    };

    let mut found_match = false;

    for path in paths {
        if path.is_file() {
            if let Err(e) = search_file(&path, &matcher, &formatter, &mut found_match, &args) {
                if !args.silent {
                    eprintln!("Error: {}", e);
                }
            }
        } else if path.is_dir() {
            if let Err(e) = search_directory(&path, &matcher, &formatter, &mut found_match, &args) {
                if !args.silent {
                    eprintln!("Error: {}", e);
                }
            }
        }
    }
}

fn search_file(
    path: &Path,
    matcher: &Matcher,
    formatter: &OutputFormatter,
    found_match: &mut bool,
    args: &Args,
) -> io::Result<()> {
    let content = fs::read_to_string(path)?;
    let matches = matcher.find_all(&content, args);

    if !matches.is_empty() {
        *found_match = true;
        if args.files_with_matches {
            println!("{}", path.display());
        } else if args.count {
            println!("{}", matches.len());
        } else {
            formatter.print_matches(path, &content, &matches, args);
        }
    }

    Ok(())
}

fn search_directory(
    dir: &Path,
    matcher: &Matcher,
    formatter: &OutputFormatter,
    found_match: &mut bool,
    args: &Args,
) -> io::Result<()> {
    if args.norecurse {
        search_directory_depth(dir, matcher, formatter, found_match, args, 0)?;
    } else {
        search_directory_depth(dir, matcher, formatter, found_match, args, args.depth)?;
    }
    Ok(())
}

fn search_directory_depth(
    dir: &Path,
    matcher: &Matcher,
    formatter: &OutputFormatter,
    found_match: &mut bool,
    args: &Args,
    depth: usize,
) -> io::Result<()> {
    if depth == 0 {
        return Ok(());
    }

    let entries = fs::read_dir(dir)?;
    for entry in entries {
        let entry = entry?;
        let path = entry.path();

        if path.is_file() {
            if !args.unrestricted && !args.all_types && !args.all_text {
                if should_ignore_file(&path, args) {
                    continue;
                }
            }

            if let Ok(content) = fs::read_to_string(&path) {
                let matches = matcher.find_all(&content, args);
                if !matches.is_empty() {
                    *found_match = true;
                    if args.files_with_matches {
                        println!("{}", path.display());
                    } else if args.count {
                        println!("{}", matches.len());
                    } else {
                        formatter.print_matches(&path, &content, &matches, args);
                    }
                }
            }
        } else if path.is_dir() && !args.norecurse {
            search_directory_depth(&path, matcher, formatter, found_match, args, depth - 1)?;
        }
    }

    Ok(())
}

fn should_ignore_file(path: &Path, args: &Args) -> bool {
    let path_str = path.to_string_lossy();

    // Ignore .git directories
    if path_str.contains("/.git/") {
        return true;
    }

    // Ignore patterns from .gitignore if not unrestricted
    if !args.unrestricted && !args.skip_vcs_ignores {
        // TODO: Parse .gitignore files
    }

    false
}

fn print_usage() {
    eprintln!("Usage: ag [OPTIONS] PATTERN [PATH]");
    eprintln!("Use --help for more options");
}

fn print_file_types() {
    let types = vec![
        ("actionscript", vec![".as", ".mxml"]),
        ("ada", vec![".ada", ".adb", ".ads"]),
        ("asciidoc", vec![".adoc", ".ad", ".asc", ".asciidoc"]),
        ("apl", vec![".apl"]),
        ("asm", vec![".asm", ".s"]),
        ("asp", vec![".asp", ".asa", ".aspx", ".asax", ".ashx", ".ascx", ".asmx"]),
        ("c", vec![".c", ".h"]),
        ("cc", vec![".cc", ".cpp", ".cxx", ".h", ".hpp"]),
        ("go", vec![".go"]),
        ("html", vec![".htm", ".html", ".shtml", ".xhtml"]),
        ("java", vec![".java"]),
        ("javascript", vec![".js"]),
        ("python", vec![".py"]),
        ("ruby", vec![".rb"]),
        ("rust", vec![".rs"]),
        ("shell", vec![".sh", ".bash"]),
    ];

    println!("The following file types are supported:");
    for (name, exts) in types {
        println!("  --{}", name);
        for ext in exts {
            print!("      {}", ext);
        }
        println!();
    }
}
