    literal: bool,
    ignore_case: bool,
    word_regexp: bool,
    invert_match: bool,
}

impl Matcher {
    pub fn new(args: &Args) -> Result<Self, String> {
        Ok(Matcher {
            pattern: args.pattern.clone(),
            literal: args.literal,
            ignore_case: args.ignore_case || (args.smart_case && !args.pattern.chars().any(|c| c.is_uppercase())),
            word_regexp: args.word_regexp,
            invert_match: args.invert_match,
        })
    }

    pub fn find_all(&self, text: &str, args: &Args) -> Vec<Match> {
        let mut matches = Vec::new();

        for (line_num, line) in text.lines().enumerate() {
            if self.line_matches(line) {
                // Find all matches in this line
                if let Some(m) = self.find_matches_in_line(line, line_num + 1) {
                    matches.extend(m);
                }
            }
        }

