            // Return lines that don't match
            let matching_lines: std::collections::HashSet<usize> = matches.iter().map(|m| m.line_num).collect();
            let mut inverted = Vec::new();
            for (line_num, line) in text.lines().enumerate() {
                if !matching_lines.contains(&(line_num + 1)) {
                    inverted.push(Match {
                        line_num: line_num + 1,
                        col: 1,
                        matched_text: line.to_string(),
                        line_text: line.to_string(),
                    });
                }
            }
            return inverted;
