mod args;
mod matcher;
mod output;
mod ignore;
mod utils;

use args::Args;
use matcher::Matcher;
use output::OutputFormatter;
use utils::normalize_path;

fn main() {
    let args = match Args::parse() {
        Ok(a) => a,
        Err(e) => {
            eprintln!("Error: {}", e);
            process::exit(1);
        }
    };

    if args.version {
        println!("ag version 2.2.0\n");
        println!("Features:");
        println!("  +jit +lzma +zlib");
        return;
    }

    if args.list_file_types {
        print_file_types();
        return;
    }

    if args.pattern.is_empty() && !args.help {
        print_usage();
        return;
    }

    let matcher = match Matcher::new(&args) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Regex error: {}", e);
            process::exit(1);
        }
    };

    // Determine if we should show filenames
    let mut args = args;
    if args.paths.len() == 1 && args.paths[0].is_file() {
        // Single file - don't show filename by default
        args.filename = false;
        args.numbers = true;
    } else if args.paths.is_empty() {
        // Default directory - show filenames
        args.filename = true;
        args.numbers = true;
    } else if args.paths.len() > 1 {
        // Multiple paths - show filenames
        args.filename = true;
        args.numbers = true;
    }

    let formatter = OutputFormatter::new(&args);

    let paths = if args.paths.is_empty() {
        vec![PathBuf::from(".")]
    } else {
        args.paths.clone()
    };

    let mut _found_match = false;

    for path in paths {
        if path.is_file() {
            if let Err(e) = search_file(&path, &matcher, &formatter, &mut _found_match, &args) {
                if !args.silent {
                    eprintln!("Error: {}", e);
                }
            }
        } else if path.is_dir() {
            if let Err(e) = search_directory(&path, &matcher, &formatter, &mut _found_match, &args) {
                if !args.silent {
                    eprintln!("Error: {}", e);
                }
            }
        }
    }
}

fn search_file(
    path: &Path,
    matcher: &Matcher,
    formatter: &OutputFormatter,
    found_match: &mut bool,
    args: &Args,
) -> io::Result<()> {
    let content = fs::read_to_string(path)?;
    let matches = matcher.find_all(&content, args);

    if !matches.is_empty() {
        *found_match = true;
        if args.files_with_matches {
            println!("{}", normalize_path(path));
        } else if args.count {
            println!("{}", matches.len());
        } else {
            formatter.print_matches(path, &content, &matches, args);
        }
    }

    Ok(())
}

fn search_directory(
    dir: &Path,
    matcher: &Matcher,
    formatter: &OutputFormatter,
    found_match: &mut bool,
    args: &Args,
) -> io::Result<()> {
    if args.norecurse {
        search_directory_depth(dir, matcher, formatter, found_match, args, 0)?;
    } else {
        search_directory_depth(dir, matcher, formatter, found_match, args, args.depth)?;
    }
    Ok(())
}

fn search_directory_depth(
    dir: &Path,
    matcher: &Matcher,
    formatter: &OutputFormatter,
    found_match: &mut bool,
    args: &Args,
    depth: usize,
) -> io::Result<()> {
