use crate::args::Args;
use crate::matcher::Match;
use crate::utils::normalize_path;
use std::path::Path;

pub struct OutputFormatter {
    color_path: String,
    color_line_number: String,
    color_match: String,
}

impl OutputFormatter {
    pub fn new(args: &Args) -> Self {
        OutputFormatter {
            color_path: args.color_path.clone(),
            color_line_number: args.color_line_number.clone(),
            color_match: args.color_match.clone(),
        }
    }

    pub fn print_matches(&self, path: &Path, content: &str, matches: &[Match], args: &Args) {
        if args.only_matching {
            for mat in matches {
                println!("{}", mat.matched_text);
            }
            return;
        }

        if args.vimgrep {
            println!("{}:{}:{}:{}", normalize_path(path), matches[0].line_num, matches[0].col, matches[0].line_text);
            return;
        }

        // Normal output
        let lines: Vec<&str> = content.lines().collect();

        for (idx, mat) in matches.iter().enumerate() {
            let line_idx = mat.line_num - 1;

            // Handle context
            if let Some(ctx) = args.context {
                if idx == 0 || matches[idx - 1].line_num != mat.line_num - 1 {
                    let start = if line_idx >= ctx { line_idx - ctx } else { 0 };
                    let end = (line_idx + ctx + 1).min(lines.len());

                    for i in start..end {
                        if i == line_idx {
                            self.print_match_line(path, i + 1, lines[i], args);
                        } else {
                            self.print_context_line(i + 1, lines[i]);
                        }
                    }
                }
            } else if let Some(before) = args.before_context {
                if idx == 0 || matches[idx - 1].line_num != mat.line_num {
                    let start = if line_idx >= before { line_idx - before } else { 0 };
                    for i in start..=line_idx {
                        if i == line_idx {
                            self.print_match_line(path, i + 1, lines[i], args);
                        } else {
                            self.print_context_line(i + 1, lines[i]);
                        }
                    }
                }
            } else if let Some(after) = args.after_context {
                if idx == 0 || matches[idx - 1].line_num != mat.line_num {
                    for i in line_idx..=(line_idx + after).min(lines.len() - 1) {
                        if i == line_idx {
                            self.print_match_line(path, i + 1, lines[i], args);
                        } else {
                            self.print_context_line(i + 1, lines[i]);
                        }
                    }
                }
            } else {
                self.print_match_line(path, mat.line_num, &mat.line_text, args);
            }
        }
    }

    fn print_match_line(&self, path: &Path, line_num: usize, line: &str, args: &Args) {
        let mut output = String::new();

        if args.filename {
            output.push_str(&format!("{}:", normalize_path(path)));
        }

        if args.column {
            output.push_str(&format!("{}:1:", line_num));
        } else if args.numbers || args.filename {
            output.push_str(&format!("{}:", line_num));
        }

        output.push_str(line);
        println!("{}", output);
    }

    fn print_context_line(&self, line_num: usize, line: &str) {
        println!("{}-{}", line_num, line);
    }
}
