            }
        }
        "--depth" => {
            i += 1;
            if i < args.len() && looks_like_number(&args[i]) {
                result.depth = args[i].parse().unwrap_or(25);
                i += 1;
            }
        }
        "-m" | "--max-count" => {
            i += 1;
            if i < args.len() && looks_like_number(&args[i]) {
                result.max_count = args[i].parse().unwrap_or(10000);
                i += 1;
            }
        }
        "--ignore" | "--ignore-dir" => {
            i += 1;
            if i < args.len() {
                result.ignore_patterns.push(args[i].clone());
                i += 1;
            }
        }
        "-p" | "--path-to-ignore" => {
            i += 1;
            if i < args.len() {
                result.ignore_file = Some(PathBuf::from(&args[i]));
                i += 1;
            }
        }
        "--pager" => {
            i += 1;
            if i < args.len() {
                result.pager = Some(args[i].clone());
                i += 1;
            }
        }
        "--color-path" => {
            i += 1;
            if i < args.len() {
                result.color_path = args[i].clone();
                i += 1;
            }
        }
        "--color-line-number" => {
            i += 1;
            if i < args.len() {
                result.color_line_number = args[i].clone();
                i += 1;
            }
        }
        "--color-match" => {
            i += 1;
            if i < args.len() {
                result.color_match = args[i].clone();
                i += 1;
            }
        }
        "-g" => {
            i += 1;
            if i < args.len() {
                i += 1;
            }
        }
        "-G" | "--file-search-regex" => {
